import fs from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  artifactDigest,
  type ArtifactManifest,
} from "../../src/lib/project/artifact-manifest.js";
import {
  lineEndingNormalizedDigest,
  prepareArtifactScope,
} from "../../src/lib/project/artifact-scope.js";

const OUT = "src/types/generated";
const FILE = `${OUT}/index.d.ts`;
const LF =
  '// Auto-generated by vext typegen. DO NOT EDIT.\n/// <reference path="x" />\nexport {};\n';
const CRLF = LF.replaceAll("\n", "\r\n");

let root = "";
beforeEach(() => {
  root = fs.realpathSync(fs.mkdtempSync(path.join(tmpdir(), "vext-eol-")));
  fs.mkdirSync(path.join(root, OUT), { recursive: true });
});
afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

const manifest = (
  files: Array<{ path: string; sha256: string }> = [],
): ArtifactManifest => ({
  schemaVersion: 1,
  realRoot: root,
  scopes: files.length
    ? [
        {
          id: `typegen:${OUT}`,
          producer: "typegen",
          outputDir: OUT,
          producerVersion: "test",
          inputDigest: null,
          generation: 1,
          files,
        },
      ]
    : [],
});
const write = (contents: string | Buffer) =>
  fs.writeFileSync(path.join(root, FILE), contents);
const prepare = (m: ArtifactManifest, contents = LF) =>
  prepareArtifactScope(
    root,
    m,
    OUT,
    {
      outDir: OUT,
      producer: "typegen",
      files: [{ path: path.join(root, FILE), contents }],
    },
    "test",
  );

describe("artifact ownership line endings", () => {
  it("adopts an unrecorded CRLF checkout of the exact generated output without rewriting", () => {
    write(CRLF);
    const result = prepare(manifest());
    expect(result.changes).toEqual([]);
    expect(result.scope.files).toEqual([
      { path: FILE, sha256: artifactDigest(LF) },
    ]);
  });

  it("accepts a recorded LF output that was re-checked-out as CRLF", () => {
    write(CRLF);
    const result = prepare(
      manifest([{ path: FILE, sha256: artifactDigest(LF) }]),
    );
    expect(result.changes).toEqual([]);
  });

  it("rewrites a CRLF copy of the recorded output when the producer output changes", () => {
    write(CRLF);
    const next = `${LF}export type Extra = 1;\n`;
    const result = prepare(
      manifest([{ path: FILE, sha256: artifactDigest(LF) }]),
      next,
    );
    expect(result.changes).toHaveLength(1);
    expect(result.changes[0]!.after?.toString()).toBe(next);
  });

  it("still rejects real edits, with either line ending", () => {
    write(CRLF.replace("export {};", "export const edited = 1;"));
    expect(() => prepare(manifest())).toThrow(
      /VEXT_OUTPUT_CONFLICT|recorded producer/,
    );
    write(LF.replace("export {};", "export const edited = 1;"));
    expect(() =>
      prepare(manifest([{ path: FILE, sha256: artifactDigest(LF) }])),
    ).toThrow(/recorded producer/);
  });

  it("does not treat lone CR or LF-only differences as equivalent", () => {
    write(LF.replaceAll("\n", "\r"));
    expect(() => prepare(manifest())).toThrow(/recorded producer/);
  });

  it("never normalizes binary content", () => {
    expect(
      lineEndingNormalizedDigest(Buffer.from([0x61, 0x0d, 0x0a, 0x00])),
    ).toBeNull();
    expect(lineEndingNormalizedDigest(Buffer.from(LF))).toBeNull();
    expect(lineEndingNormalizedDigest(Buffer.from(CRLF))).toBe(
      artifactDigest(LF),
    );
  });

  it("accepts Windows-style candidate paths under the output directory", () => {
    write(CRLF);
    const windowsPath = path.join(root, ...FILE.split("/"));
    const result = prepareArtifactScope(
      root,
      manifest(),
      OUT,
      {
        outDir: OUT,
        producer: "typegen",
        files: [{ path: windowsPath, contents: LF }],
      },
      "test",
    );
    expect(result.scope.files[0]!.path).toBe(FILE);
  });
});
